int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event)
{
    /* Return 1 if the event is a software event */
    if (event->attr.type == PERF_TYPE_SOFTWARE)
        return 1;

    /* Verify event's PMU matches the leader PMU and state is valid */
    if (event->pmu != event->group_leader->pmu || event->state < PERF_EVENT_STATE_OFF)
        return 0;

    /* If event is off and not enabled on execution, return 1 */
    if (event->state == PERF_EVENT_STATE_OFF && !(event->attr.enable_on_exec))
        return 1;

    /* Check if the event index can be retrieved from the ARM PMU structure */
    if (event->hw.idx >= 0 && event->hw.idx < ARM_PMC_MAX_COUNTERS)
        return 1;

    return 0;
}

int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->pmu->type == PERF_TYPE_SOFTWARE)
        return 1;

    if (event->pmu != event->group_leader->pmu)
        return 0;

    if (event->state < PERF_EVENT_STATE_OFF)
        return 0;

    if (event->state == PERF_EVENT_STATE_OFF && !(event->hw.flags & PERF_EVENT_FLAG_ENABLED_ON_EXEC))
        return 1;

    int idx = arm_pmu_event_idx(event);
    return (idx >= 0) ? 1 : 0;
}

int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event)
{
    /* Return 1 if the event is a software event */
    if (is_software_event(event))
        return 1;

    /* Check if the event's PMU matches the leader PMU */
    if (event->pmu != event->group_leader->pmu)
        return 0;

    /* Check if the event's state is at least PERF_EVENT_STATE_OFF */
    if (event->state < PERF_EVENT_STATE_OFF)
        return 0;

    /* If the event is off and not enabled on execution, return 1 */
    if (event->state == PERF_EVENT_STATE_OFF && !(event->hw.config & PERF_EXEC_OUTPUT))
        return 1;

    /* Retrieve the event index from the ARM PMU structure */
    int idx = arm_pmu_idx(event);

    if (idx >= 0)
        return 1;
    else
        return 0;
}

int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->event_type == PERF_TYPE_SOFTWARE)
        return 1;

    if (event->pmu != event->leader->pmu || event->state < PERF_EVENT_STATE_OFF)
        return 0;

    if (event->state == PERF_EVENT_STATE_OFF && !(event->hw.config_base & ARM_PMU_EN_EXEC))
        return 1;

    int idx = arm_pmu_event_idx(hw_events, event);
    return (idx >= 0) ? 1 : 0;
}

int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->hw.flags & PERF_EVENT_FLAG_SOFTWARE)
        return 1;

    if (event->pmu != event->group_leader->pmu ||
        event->state < PERF_EVENT_STATE_OFF)
        return 0;

    if (event->state == PERF_EVENT_STATE_OFF && !(event->hw.config & ARM_PMC_EE))
        return 1;

    if (event->hw.idx < 0)
        return 0;

    return 1;
}
